import { useEffect, useMemo, useRef, useState, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import { Box } from '@chakra-ui/react';
import { CodeTab, PreviewTab, TabsLayout } from '../../components/common/TabsLayout';
import CodeHighlighter from '../../components/code/CodeHighlighter';
import CodeExample from '../../components/code/CodeExample';
import Customize from '../../components/common/Preview/Customize';
import PreviewSlider from '../../components/common/Preview/PreviewSlider';
import PreviewSwitch from '../../components/common/Preview/PreviewSwitch';
import PreviewSelect from '../../components/common/Preview/PreviewSelect';
import PreviewColorPickerCustom from '../../components/common/Preview/PreviewColorPickerCustom';
import PreviewInput from '../../components/common/Preview/PreviewInput';
import { Monitor, Tablet, Smartphone, RotateCw } from 'lucide-react';
import { PRO_INDEX } from '../../constants/ProCatalog';

/**
 * One generic demo for every Pro component.
 *
 * The preview renders inside the isolated /preview.html iframe: the site chrome
 * is Chakra, whose global @layer reset collides with vault Tailwind utilities
 * when both share a document (symptom: text-5xl computing to 16px). Upstream
 * never mixes the two either — their inline demos all use CSS variants.
 *
 * The Customize panel is driven by per-component control schemas in PRO_INDEX
 * (generated by scripts/add-pro.ts from agent-extracted prop interfaces).
 * Changes post into the iframe via postMessage, so tweaking a slider re-renders
 * the component without reloading the frame (which would restart WebGL).
 */

const SOURCES = {
  ...import.meta.glob('../../../../vault/reactbits-starter/components/*/variants/*/*.{tsx,jsx,css}', { query: '?raw', import: 'default' }),
  ...import.meta.glob('../../../../vault/reactbits-pro/blocks/*/files/*.{tsx,jsx}', { query: '?raw', import: 'default' }),
  ...import.meta.glob('../../../../vault/reactbits-pro/agent-kit/*/*.md', { query: '?raw', import: 'default' })
};

const findKey = (map, filePath) => Object.keys(map).find(k => k.endsWith(filePath.replace(/^vault/, '')));

const controlDefaults = controls =>
  Object.fromEntries((controls || []).map(c => [c.prop, c.default]));

// Controls may address array elements as "colors[0]" — fold those flat keys
// into real arrays so the component receives colors: [a, b, c, d].
const foldIndexed = flat => {
  const out = {};
  for (const [k, v] of Object.entries(flat)) {
    const m = k.match(/^(\w+)\[(\d+)\]$/);
    if (m) {
      if (!Array.isArray(out[m[1]])) out[m[1]] = [];
      out[m[1]][+m[2]] = v;
    } else out[k] = v;
  }
  return out;
};

const readProp = (props, key) => {
  const m = key.match(/^(\w+)\[(\d+)\]$/);
  return m ? props[m[1]]?.[+m[2]] : props[key];
};

export default function ProDemo() {
  const { subcategory } = useParams();
  const meta = PRO_INDEX[subcategory];
  const [source, setSource] = useState('');
  const frameRef = useRef(null);
  // Pro-site toolbar parity: preview at desktop / tablet / phone widths, and a
  // refresh that remounts the iframe to replay the animation from the start.
  const [viewWidth, setViewWidth] = useState('100%');
  const [frameKey, setFrameKey] = useState(0);

  const initialProps = useMemo(
    () => ({ ...foldIndexed(controlDefaults(meta?.controls)), ...(meta?.demoProps || {}) }),
    [meta]
  );
  const [props, setProps] = useState(initialProps);
  useEffect(() => setProps(initialProps), [initialProps]);

  const stage = meta?.stage || (meta?.fill || meta?.kind === 'block' ? 'fill' : 'center');

  // Src is built from the INITIAL props only — later changes go through
  // postMessage so the iframe (and any WebGL context inside) never reloads.
  const previewSrc = useMemo(() => {
    if (!meta?.file) return null;
    const q = new URLSearchParams({
      path: meta.file,
      export: meta.exportName || '',
      fit: stage,
      props: JSON.stringify(initialProps)
    });
    return `/preview.html?${q.toString()}`;
  }, [meta?.file, meta?.exportName, stage, initialProps]);

  const updateProp = useCallback((prop, value) => {
    setProps(prev => {
      const m = prop.match(/^(\w+)\[(\d+)\]$/);
      let next;
      if (m) {
        const arr = Array.isArray(prev[m[1]]) ? [...prev[m[1]]] : [];
        arr[+m[2]] = value;
        next = { ...prev, [m[1]]: arr };
      } else {
        next = { ...prev, [prop]: value };
      }
      frameRef.current?.contentWindow?.postMessage({ type: 'foxbits:props', props: next }, '*');
      return next;
    });
  }, []);

  const resetProps = useCallback(() => {
    setProps(initialProps);
    frameRef.current?.contentWindow?.postMessage({ type: 'foxbits:props', props: initialProps }, '*');
  }, [initialProps]);

  useEffect(() => {
    if (!meta?.file) return;
    const key = findKey(SOURCES, meta.file);
    if (!key) return;
    let cancelled = false;
    SOURCES[key]()
      .then(s => !cancelled && setSource(s))
      .catch(() => !cancelled && setSource(''));
    return () => {
      cancelled = true;
    };
  }, [meta?.file]);

  // The css-variant sources feed the Code tab's variant switcher; the tw
  // source doubles for the JS presets since Pro ships TypeScript only.
  const [cssVariant, setCssVariant] = useState({ tsx: '', css: '' });
  useEffect(() => {
    if (!meta?.file) return;
    const cssDir = meta.file.replace('/variants/tw/', '/variants/css/');
    const tsxKey = findKey(SOURCES, cssDir);
    const cssKey = Object.keys(SOURCES).find(k => k.includes(cssDir.replace(/\/[^/]*$/, '/')) && k.endsWith('.css'));
    let cancelled = false;
    Promise.all([
      tsxKey ? SOURCES[tsxKey]() : Promise.resolve(''),
      cssKey ? SOURCES[cssKey]() : Promise.resolve('')
    ]).then(([tsx, css]) => !cancelled && setCssVariant({ tsx, css }));
    return () => { cancelled = true; };
  }, [meta?.file]);

  const codeObject = useMemo(() => {
    if (!source) return null;
    const propsStr = Object.entries(meta?.demoProps || {})
      // Copied usage must contain ONLY real component props: no styling helpers
      // and no preview-only keys (__sequence, __cardContent drive the demo
      // stage, they are not props the installed component understands).
      .filter(([k, v]) =>
        !k.startsWith('__') &&
        !['className', 'style', 'children'].includes(k) &&
        (['string', 'number', 'boolean'].includes(typeof v) || Array.isArray(v)))
      .slice(0, 6)
      .map(([k, v]) => typeof v === 'string' ? `  ${k}="${v}"` : `  ${k}={${JSON.stringify(v)}}`)
      .join('\n');
    const file = meta.file.split('/').pop().replace(/\.tsx$/, '');
    const cc = meta.demoProps?.__cardContent;
    // Children matching what the demo renders, so pasted usage reproduces it.
    const childLines = cc
      ? ['  <div>', cc.title && `    <h3>${cc.title}</h3>`, cc.description && `    <p>${cc.description}</p>`,
         cc.button && `    <button>${cc.button}</button>`, '  </div>'].filter(Boolean).join('\n')
      : null;
    const tag = childLines
      ? `<${meta.exportName}\n${propsStr}\n>\n${childLines}\n</${meta.exportName}>`
      : `<${meta.exportName}\n${propsStr}\n/>`;
    // A demo __sequence means the effect rides a prop TRANSITION (Preloader's
    // stairs exit fires when loading flips false). Static props cannot show
    // that, so the snippet demonstrates the stateful pattern instead.
    const seq = Array.isArray(meta.demoProps?.__sequence) ? meta.demoProps.__sequence[0] : null;
    const seqProp = seq && seq.set ? Object.keys(seq.set)[0] : null;
    const cap = k => k[0].toUpperCase() + k.slice(1);
    const usage = seqProp
      ? `import { useEffect, useState } from 'react';\nimport { ${meta.exportName} } from './${file}';\n\n` +
        `const [${seqProp}, set${cap(seqProp)}] = useState(${JSON.stringify(meta.demoProps[seqProp])});\n` +
        `// flip when your real work finishes (the demo uses a timer)\n` +
        `useEffect(() => {\n  const t = setTimeout(() => set${cap(seqProp)}(${JSON.stringify(seq.set[seqProp])}), ${seq.after ?? 2000});\n  return () => clearTimeout(t);\n}, []);\n\n` +
        tag.replace(`${seqProp}={${JSON.stringify(meta.demoProps[seqProp])}}`, `${seqProp}={${seqProp}}`)
      : `import { ${meta.exportName} } from './${file}';\n\n${tag}`;
    return {
      tsTailwind: source,
      tailwind: source,
      tsCode: cssVariant.tsx || source,
      code: cssVariant.tsx || source,
      css: cssVariant.css || undefined,
      usage,
      dependencies: (meta.dependencies || []).join(', ')
    };
  }, [source, cssVariant, meta]);

  if (!meta) {
    return (
      <Box p={6} color="#a1a1aa">
        Unknown Pro asset: <code>{subcategory}</code>
      </Box>
    );
  }

  const markdownDoc = useMemo(() => {
    if (!meta || !codeObject) return '';
    const props = (meta.controls || [])
      .map(c => `| ${'`'}${c.prop}${'`'} | ${c.control} | ${'`'}${JSON.stringify(c.default)}${'`'} |`)
      .join('\n');
    return [
      `# ${meta.title}`,
      '',
      meta.description || '',
      '',
      '## Install',
      '',
      '```bash',
      `npx shadcn@latest add @reactbits-starter/${meta.id.split('/').pop()}-tw`,
      '```',
      '',
      '## Usage',
      '',
      '```tsx',
      codeObject.usage,
      '```',
      '',
      props ? '## Props\n\n| Prop | Control | Default |\n|---|---|---|\n' + props : '',
      '',
      meta.dependencies?.length ? `Dependencies: ${meta.dependencies.join(', ')}` : ''
    ].join('\n');
  }, [meta, codeObject]);

  const isDoc = ['skill', 'prompt', 'recipe'].includes(meta.kind);
  const isBlock = meta.kind === 'block';
  const controls = meta.controls || [];
  const hasChanges = JSON.stringify(props) !== JSON.stringify(initialProps);

  return (
    <TabsLayout>
      <PreviewTab>
        <Box mb={4}>
          {/* page title comes from CategoryPage — repeating it here doubled
              every Deep page's heading (user, 2026-08-15) */}
          {meta.description && (
            <Box color="#a1a1aa" mt={2}>
              {meta.description}
            </Box>
          )}
          <Box mt={3} display="flex" gap="8px" flexWrap="wrap" fontSize="11px">
            <Box px={2} py="2px" borderRadius="6px" bg="rgba(82,39,255,.25)" color="#c4b5fd">
              DEEP
            </Box>
            {meta.tags?.slice(0, 6).map(t => (
              <Box key={t} px={2} py="2px" borderRadius="6px" bg="#1a1a1a" color="#a1a1aa">
                {t}
              </Box>
            ))}
          </Box>
        </Box>

        {isDoc ? (
          <CodeHighlighter language="markdown" codeString={source || 'Loading…'} />
        ) : (
          <>
            <Box display="flex" justifyContent="flex-end" flexWrap="wrap" gap="6px" mb={2}>
              {/* viewport presets mean nothing ON a phone — hide below md */}
              {[
                { icon: Monitor, w: '100%', label: 'Desktop preview' },
                { icon: Tablet, w: '768px', label: 'Tablet preview' },
                { icon: Smartphone, w: '390px', label: 'Phone preview' }
              ].map(({ icon: Icon, w, label }) => (
                <Box
                  key={w}
                  as="button"
                  aria-label={label}
                  onClick={() => setViewWidth(w)}
                  display={{ base: 'none', md: 'block' }}
                  p="8px"
                  borderRadius="10px"
                  bg={viewWidth === w ? '#27232f' : '#171420'}
                  border="1px solid #2a2633"
                  color={viewWidth === w ? '#fff' : '#a1a1aa'}
                  cursor="pointer"
                  _hover={{ color: '#fff' }}
                >
                  <Icon size={15} />
                </Box>
              ))}
              <Box
                as="button"
                aria-label="Replay preview"
                onClick={() => setFrameKey(k => k + 1)}
                p="8px"
                borderRadius="10px"
                bg="#171420"
                border="1px solid #2a2633"
                color="#a1a1aa"
                cursor="pointer"
                _hover={{ color: '#fff' }}
              >
                <RotateCw size={15} />
              </Box>
            </Box>
            <Box position="relative" className="demo-container" h={{ base: 420, md: isBlock ? 620 : 500 }} p={0} overflow="hidden"
                 display="flex" justifyContent="center" bg="#060608">
              {previewSrc ? (
                <iframe
                  key={frameKey}
                  ref={frameRef}
                  src={previewSrc}
                  title={meta.title}
                  style={{ width: viewWidth, maxWidth: '100%', height: '100%', border: 0,
                           background: '#060608',
                           borderLeft: viewWidth !== '100%' ? '1px solid #2a2633' : 'none',
                           borderRight: viewWidth !== '100%' ? '1px solid #2a2633' : 'none' }}
                />
              ) : (
                <Box p={6} color="#f87171">Source not found: {meta.file}</Box>
              )}
            </Box>
          </>
        )}

        {!isDoc && controls.length > 0 && (
          <Customize>
            {hasChanges && (
              <Box
                as="button"
                onClick={resetProps}
                mb={3}
                fontSize="13px"
                color="#a1a1aa"
                _hover={{ color: '#fff' }}
                cursor="pointer"
              >
                ↺ Reset
              </Box>
            )}
            {controls.map(c => {
              const value = readProp(props, c.prop);
              switch (c.control) {
                case 'slider':
                  return (
                    <PreviewSlider
                      key={c.prop}
                      title={c.label}
                      min={c.min ?? 0}
                      max={c.max ?? 100}
                      step={c.step ?? 1}
                      value={typeof value === 'number' ? value : (c.default ?? 0)}
                      onChange={v => updateProp(c.prop, v)}
                    />
                  );
                case 'switch':
                  return (
                    <PreviewSwitch
                      key={c.prop}
                      title={c.label}
                      isChecked={!!value}
                      onChange={v => updateProp(c.prop, v)}
                    />
                  );
                case 'select':
                  return (
                    <PreviewSelect
                      key={c.prop}
                      title={c.label}
                      options={c.options || []}
                      value={String(value ?? '')}
                      onChange={v => updateProp(c.prop, v)}
                    />
                  );
                case 'color':
                  return (
                    <PreviewColorPickerCustom
                      key={c.prop}
                      title={c.label}
                      color={String(value ?? '#ffffff')}
                      onChange={v => updateProp(c.prop, v)}
                    />
                  );
                case 'text':
                  return (
                    <PreviewInput
                      key={c.prop}
                      title={c.label}
                      value={String(value ?? '')}
                      onChange={v => updateProp(c.prop, v)}
                    />
                  );
                default:
                  return null;
              }
            })}
          </Customize>
        )}

        {!isDoc && meta.dependencies?.length > 0 && (
          <Box mt={4} fontSize="13px" color="#a1a1aa">
            Dependencies: <code>{meta.dependencies.join(', ')}</code>
          </Box>
        )}
        <Box mt={2} fontSize="13px" color="#71717a">
          Install: <code>p4rts add {subcategory.replace(/-pro$/, '')}</code>
        </Box>
      </PreviewTab>

      <CodeTab>
        {isDoc || !codeObject ? (
          <CodeHighlighter language={isDoc ? 'markdown' : 'jsx'} codeString={source || 'Loading…'} />
        ) : (
          <CodeExample codeObject={codeObject} componentName={meta.exportName} markdownDoc={markdownDoc} />
        )}
      </CodeTab>
    </TabsLayout>
  );
}
